fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    // Pre-allocate a vector of capacity n to avoid reallocations.
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut i = 0;
    while i < n {
        // At this point:
        //  - 0 <= i <= n
        //  - result.len() == i
        //  - all elements in result are 1
        result.push(1);
        i += 1;
    }

    // Now i == n and result.len() == n, and every element is 1.
    result
}

